using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CityMobileFinalize{
const string RuntimeScene="Assets/Scenes/Oasis/MobileOptimization/Gangstar City.unity",R="FinalEnvironmentRoadReview/MobileOptimization/";static bool baking;static double bakeStart;
static CityMobileFinalize(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;if(baking){if(StaticOcclusionCulling.isRunning||EditorApplication.timeSinceStartup-bakeStart<5)return;baking=false;Finish();return;}if(!File.Exists("CityMobileFinalize.request"))return;File.Delete("CityMobileFinalize.request");try{Run();}catch(Exception e){File.WriteAllText(R+"Finalize.txt",e.ToString());Debug.LogException(e);}}
static void Run(){var sc=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");if(!sc.IsValid())sc=SceneManager.GetActiveScene();EditorSceneManager.SaveScene(sc);if(sc.path!=RuntimeScene){EditorSceneManager.SaveScene(sc,RuntimeScene,true);AssetDatabase.Refresh();string text=File.ReadAllText(RuntimeScene).Replace("smallestHole: 0.25","smallestHole: 1").Replace("backfaceThreshold: 45","backfaceThreshold: 100");File.WriteAllText(RuntimeScene,text);AssetDatabase.ImportAsset(RuntimeScene);sc=EditorSceneManager.OpenScene(RuntimeScene,OpenSceneMode.Single);}CityMobileOptimizationBuild.Backup("ProjectSettings/EditorBuildSettings.asset");var scenes=EditorBuildSettings.scenes;for(int i=0;i<scenes.Length;i++)if(scenes[i].path=="Assets/Scenes/Oasis/Gangstar City.unity")scenes[i]=new EditorBuildSettingsScene(RuntimeScene,scenes[i].enabled);EditorBuildSettings.scenes=scenes;
int buildings=0;foreach(var r in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true))){if(r.GetComponentInParent<Rigidbody>())continue;var flags=GameObjectUtility.GetStaticEditorFlags(r.gameObject);flags&=~StaticEditorFlags.BatchingStatic;flags|=StaticEditorFlags.OccludeeStatic;bool occluder=r.enabled&&r.gameObject.activeInHierarchy&&r.sharedMaterial&&r.sharedMaterial.name.StartsWith("Building")&&r.bounds.size.y>5&&!r.name.StartsWith("Mobile LOD");if(occluder){flags|=StaticEditorFlags.OccluderStatic;buildings++;}else flags&=~StaticEditorFlags.OccluderStatic;GameObjectUtility.SetStaticEditorFlags(r.gameObject,flags);}var areaGO=sc.GetRootGameObjects().FirstOrDefault(g=>g.name=="City Mobile Occlusion View Volume");if(!areaGO){areaGO=new GameObject("City Mobile Occlusion View Volume");SceneManager.MoveGameObjectToScene(areaGO,sc);areaGO.transform.position=new Vector3(200,65,-50);var area=areaGO.AddComponent<OcclusionArea>();area.center=Vector3.zero;area.size=new Vector3(1700,140,1700);}EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);File.WriteAllText(R+"Finalize.txt","Occlusion bake started for runtime scene. Building occluders="+buildings+". Original editing scene retained; Android build scene now points to optimized runtime copy with same scene name. Meshes remain separate.\n");bool started=StaticOcclusionCulling.GenerateInBackground();if(!started)throw new Exception("Occlusion bake could not start");bakeStart=EditorApplication.timeSinceStartup;baking=true;}
static void Finish(){try{var sc=SceneManager.GetSceneByPath(RuntimeScene);EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);File.AppendAllText(R+"Finalize.txt","Occlusion bake completed; data bytes="+new FileInfo("Assets/Scenes/Oasis/MobileOptimization/Gangstar City/OcclusionCullingData.asset").Length+"\n");File.WriteAllText("CityMobileVerify.request","run");}catch(Exception e){File.AppendAllText(R+"Finalize.txt",e.ToString());}}
}
